from h import *
R(9330923,"مربى الفراولة بدون سكر [بدون بكتين!]",
"كل ما تحتاجه هو مكونان فقط لتحضير مربى الفراولة اللذيذ بشكل لا يصدق والخالي من السكر!",
"28 حصة (2 ملعقة كبيرة لكل حصة)","حصة واحدة",
["2 رطل فراولة مغسولة ومنزوعة العنق (حوالي 5 أكواب مقطعة أرباعًا)","⅓ كوب بذور الشيا","2 ملعقة كبيرة شراب القيقب، اختياري"],
["قطّع الفراولة أرباعًا وضعها في قدر عريض كبير. اطهِها على نار متوسطة لمدة 6-8 دقائق حتى تلين وتغلي.","ثم ارفعها عن النار واستخدم هرّاسة البطاطس لهرس الفراولة برفق مع ترك بعض قطع الفاكهة خشنة. أضف بذور الشيا وشراب القيقب إن استخدمته وقلّب جيدًا.","ضعه جانبًا ليبرد قليلًا، ثم وزّع المربى في برطمانات نظيفة محكمة الإغلاق. يتماسك المربى تمامًا بعد تبريده في الثلاجة طوال الليل أو لمدة 4 ساعات على الأقل. احفظه في الثلاجة لاستخدامه خلال أسبوع واحد أو جمّده لمدة تصل إلى 4 أشهر."],
["استخدم برطمانات نظيفة لحفظ مربى الفراولة. إذا بدا المربى مائيًا قليلًا بعد الطهي فلا تقلق. فعندما يبرد، ستواصل بذور الشيا امتصاص السائل لتترك وراءها هلامًا سميكًا بقوام مثالي. أستخدم بذور الشيا السوداء لأنها الأسهل في العثور عليها حيث أعيش. فهي تُغمّق لون المربى قليلًا، لكن يمكنك استخدام بذور الشيا البيضاء للحصول على مربى بلون أكثر إشراقًا، إن توفرت. للحصول على قوام أخف قليلًا، قلّل بذور الشيا إلى ¼ كوب. تعطي الوصفة حوالي 3½ أكواب من مربى الفراولة. وزّعه على برطمانات صغيرة واحفظ واحدًا في الثلاجة وجمّد الباقي لاستخدامه لاحقًا. يبقى مربى الفراولة صالحًا في الثلاجة لمدة أسبوع واحد، أو يُجمَّد لمدة تصل إلى 4 أشهر."])
R(9333659,"أرز القرنبيط المقلي بالنمط الآسيوي مع صلصة الفول السوداني",
"أرز قرنبيط آسيوي بنكهة الفول السوداني مليء بالخضار ويفيض بالنكهة. ودّع الطعام الجاهز مع هذا الطبق التايلاندي البسيط واللذيذ منخفض الكربوهيدرات الذي طعمه كطعام الراحة!",
"5 حصص","حصة واحدة",
["1 حبة بصل أحمر صغيرة مقطعة شرائح","2 حبة جزر كبيرة مقشّرة ومقطعة شرائح رفيعة","1 حبة فلفل رومي أحمر كبيرة مقطعة شرائح","4 أكواب أرز القرنبيط، أي حوالي قرنبيطة صغيرة أو نصف قرنبيطة كبيرة","علبة حمص 15 أونصة مصفّاة ومشطوفة","200 جرام بازلاء الثلج","1 كوب كزبرة خضراء طازجة مفرومة (أو بصل أخضر أو بقدونس)","⅓ كوب زبدة الفول السوداني، ناعمة أو مقرمشة","3 ملاعق كبيرة عصير ليمون أخضر، أي حوالي ليمونة خضراء كبيرة","2 ملعقة كبيرة خل الأرز","2 ملعقة كبيرة تاماري أو صلصة الصويا","¾ ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة زنجبيل مطحون","1 ملعقة صغيرة سريراتشا أو أكثر","سمسم","كزبرة خضراء أو بقدونس أو بصل أخضر"],
["لتحضير أرز القرنبيط، فصّل القرنبيط إلى زهيرات وباستخدام آلة تقطيع الخضار الصغيرة أو محضّر الطعام، بشّره حتى يصبح بقوام الأرز باستخدام ملحق التقطيع. ضعه جانبًا.","ضع جميع مكونات صلصة الفول السوداني في وعاء صغير وقلّب حتى تمتزج جيدًا، ثم ضعها جانبًا.","في مقلاة كبيرة أو ووك، قلّب البصل والجزر والفلفل مع ملعقتين كبيرتين من الماء حتى تلين، أي حوالي 5 دقائق. ثم أضف أرز القرنبيط والحمص وبازلاء الثلج وقلّب لمدة 3-4 دقائق إضافية حتى يقل حجمها قليلًا دون إفراط في الطهي.","أطفئ النار وأضف الكزبرة الخضراء وصلصة الفول السوداني وقلّب جيدًا. قدّمه مرشوشًا بالسمسم ومزيد من الكزبرة الخضراء إن رغبت."],
["لا تُفرط في فرم القرنبيط. إذا لم يكن لديك ملحق التقطيع واضطررت إلى استخدام الشفرة على شكل حرف S في محضّر الطعام، فاعمل على دفعات صغيرة. قلّب بالنبض 4-5 مرات ثم تفقّده، وقلّب بالنبض أكثر إذا لزم الأمر. إذا بدا أرز القرنبيط رطبًا، فاعصر الرطوبة بمنشفة مطبخ نظيفة وجافة أو بمناديل ورقية قبل الطهي. لا تُفرط في طهي الخضار. فالخضار المقلية يجب ألا تكون طرية جدًا، وبالتأكيد ليست رخوة. لذا احرص على المراقبة بعناية وارفعها عن النار عندما تنضج. لوصفة خالية من الصويا، استبدل صلصة الصويا أو التاماري بأمينو جوز الهند، أو احذفها وأضف الملح حسب الرغبة. لوصفة خالية من الفول السوداني، يمكنك استبداله بزبدة اللوز أو زبدة البيكان أو زبدة الكاجو أو أي زبدة مكسرات تفضلها. وإذا كنت تحتاج إلى وصفة خالية تمامًا من المكسرات، فاستخدم زبدة الصويا (إن كنت تستطيع تناول الصويا) أو زبدة دوار الشمس (المصنوعة من بذور دوار الشمس) أو الطحينة (المصنوعة من بذور السمسم)، مع اختلاف طفيف في النتيجة. أجد أن هذا الطبق حار بدرجة خفيفة فقط. ولكن إذا كان تحمّلك للحرارة منخفضًا، فابدأ بنصف ملعقة صغيرة فقط من الصلصة الحارة وأضف المزيد حتى تناسبك. يبقى أرز القرنبيط الآسيوي المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام."],
{"For the Peanut Sauce":"لصلصة الفول السوداني","Optional Garnishes":"للتزيين (اختياري)"})
R(9336436,"صلصة جبن القرنبيط النباتية الصحية [حارة]",
"غموس حار بنكهة الجبن مصنوع من القرنبيط الصحي والمتعدد الاستخدامات! قدّمه فوق البروكلي المطهو على البخار، أو اغمس فيه الرقائق أو البسكويت المالح أو حتى الخضار النيئة!",
"6 حصص","حصة واحدة",
["4½ أكواب زهيرات قرنبيط من حوالي قرنبيطة صغيرة أو نصف قرنبيطة كبيرة","2-3 فلفل هالبينو","1 حبة بصل أصفر مقطعة أرباعًا","2-3 فصوص ثوم غير مقشّرة","¾-1 كوب مرق خضار قليل الصوديوم","⅓ كوب خميرة غذائية","2 ملعقة كبيرة تاماري أو صلصة الصويا إن لم تكن تتجنب الغلوتين","2 ملعقة صغيرة بابريكا مدخنة","ملح حسب الرغبة"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية) بوضع الخَبز بالهواء الساخن وبطّن صينية خبز بورق الزبدة. ثم رتّب زهيرات القرنبيط والبصل المقطع أرباعًا والهالبينو والثوم في طبقة واحدة.","اخبزها لمدة 15-20 دقيقة حتى تصبح الحواف ذهبية ويلين القرنبيط عند غرزه بالشوكة.","ثم انقل الخضار المحمّصة (بعد إزالة قشر الثوم) مع جميع المكونات المتبقية إلى الخلاط. اخلط حتى يصبح الخليط ناعمًا ثم تذوّق وأضف مزيدًا من الملح إذا لزم الأمر أو مزيدًا من المرق للتخفيف كما تريد. قدّمه مع الخضار أو البسكويت المالح أو الرقائق أو خبز البيتا."],
["اضبط كمية المرق حسب القوام الذي تفضله. وجدت أن كوبًا واحدًا يعطي القوام المثالي، لكن ابدأ بـ ¾ كوب إذا أردت غموسًا أكثر كثافة وأضف المزيد إذا لزم الأمر. إذا كان لديك خلاط قوي مثل فيتامكس، فشغّله وقتًا أطول قليلًا لتتأكد من أن صلصة جبن القرنبيط ساخنة جيدًا قبل التقديم. حضّرها مسبقًا لتوفير الوقت. يمكنك بسهولة إعادة تسخين الغموس قبل التقديم (أو تقديمه باردًا). طعمه رائع في الحالتين، لكنني أفضّله دافئًا. استخدم جبن القرنبيط النباتي بطرق متنوعة. استخدمه كغموس مع الخضار كوجبة خفيفة، أو مع الرقائق أو البسكويت المالح كمكافأة، أو اسكبه على البروكلي أو الهليون أو أي خضار مطهوّة على البخار تفضلها. يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق، أو يُجمَّد (بعد أن يبرد تمامًا) في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."])
R(9340676,"كوكيز الموز ورقائق الشوكولاتة النباتية",
"كوكيز الموز ورقائق الشوكولاتة النباتية هذه بقوام مطاطي مثالي وتكون جاهزة في وقت قصير!",
"9 قطع كوكيز","حصة واحدة",
["¾ كوب موز مهروس، أي حوالي موزتين","⅓ كوب صلصة التفاح غير المحلاة","⅓ كوب سكر قصب أو سكر جوز الهند","120 جرامًا من دقيق القمح الكامل، أي حوالي 1 كوب يُملأ بالملعقة ويُسوّى","½ ملعقة صغيرة بيكربونات الصوديوم","¼ ملعقة صغيرة ملح البحر","½ كوب رقائق الشوكولاتة الداكنة"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) وبطّن صينية خبز بورق الزبدة.","اهرس الموز في وعاء خلط وأضف صلصة التفاح والسكر. اخلط جيدًا.","بعد ذلك، أضف جميع المكونات الجافة: الدقيق وبيكربونات الصوديوم والملح وقلّب حتى تمتزج دون إفراط في الخلط. ثم أضف رقائق الشوكولاتة بالتحريك الرفيع من الأسفل إلى الأعلى.","اغرف الخليط بمغرفة كوكيز متوسطة على الصينية المجهزة مع ترك مسافة كبيرة بين كل قطعة كوكيز وأخرى. ستحصل على حوالي 9 قطع كوكيز. (أو استخدم مغرفة كوكيز صغيرة لتحصل على حوالي 18 قطعة أصغر.)","اخبز لمدة 12-15 دقيقة أو حتى تصبح الحواف والقاع ذهبية. أخرج الكوكيز من الفرن واتركه ليبرد في درجة حرارة الغرفة لمدة 15 دقيقة على الأقل قبل لمسه ونقله إلى رف التبريد."],
["استخدم موزًا ناضجًا جدًا للحصول على أفضل نكهة وحلاوة طبيعية. يجب أن يكون القشر عليه بقع بنية.","أنصح باستخدام ميزان المطبخ لوزن الدقيق للحصول على أفضل النتائج. فاغتراف الدقيق من الكيس غالبًا ما يؤدي إلى استخدام كمية زائدة منه فيصبح الكوكيز أكثر كثافة.","اترك مسافة كبيرة بين كرات عجين الكوكيز ليتمدد الكوكيز في الفرن.","يبقى الكوكيز المتبقي صالحًا في درجة حرارة الغرفة لمدة يومين، وفي الثلاجة لمدة 3-4 أيام، أو يُجمَّد لمدة تصل إلى 3 أشهر."])
R(9340739,"كرات دونات نباتية",
"كرات دونات نباتية حلوة وطرية ولذيذة للغاية بطبقة سكر وقرفة!",
"20 كرة دونات","حصة واحدة",
["150 جرامًا من دقيق الشوفان، أي حوالي 1½ كوب","¼ كوب سكر جوز الهند غير المكرر","1 ملعقة صغيرة بيكنج باودر","1 ملعقة صغيرة قرفة","⅓ كوب حليب الصويا أو حليب نباتي من اختيارك","⅓ كوب صلصة التفاح غير المحلاة","¼ كوب حليب الصويا أو حليب نباتي من اختيارك","¼ كوب سكر جوز الهند غير المكرر","2 ملعقة صغيرة قرفة"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) ودهّن صينية المافن الصغيرة إذا لزم الأمر. (تكفي لتحضير 20 كرة دونات.)","في وعاء متوسط، اخفق المكونات الجافة معًا. ثم أضف صلصة التفاح والحليب النباتي إلى الوعاء نفسه. قلّب حتى تمتزج.","استخدم مغرفة كوكيز صغيرة لتوزيع الخليط على 20 قالب مافن. لا تملأ القوالب حتى الحافة، وتذكّر أننا نصنع كرات دونات وليس مافن، لذا لا تريدها أن تفيض.","اخبزها لمدة 7-8 دقائق حتى يخرج عود الأسنان المغروز في الوسط نظيفًا في معظمه. لا تُفرط في خبزها وإلا جفّت. (فهي تنضج بسرعة لأنها صغيرة.) أخرجها من الفرن واتركها لتبرد 5-10 دقائق قبل نقلها إلى رف سلكي.","في هذه الأثناء، ضع الحليب في وعاء صغير، ثم اخلط السكر والقرفة في طبق عريض وضحل.","عندما تبرد الدونات بما يكفي للتعامل معها، لفّها واحدة تلو الأخرى في الحليب، ثم انفض الزائد، ثم لفّها في خليط السكر والقرفة حتى تتغطى من جميع الجوانب. كرر العملية مع بقية الدونات واستمتع بها!"],
["زِن الدقيق للحصول على أدق النتائج. إذا لم يكن لديك ميزان مطبخ، فاسكب الدقيق بالملعقة في كوب القياس واكشط الزائد بظهر السكين. لا تكبس الدقيق أبدًا في أكواب القياس ولا تغترفه من الكيس.","استخدم بيكنج باودر فعّالًا. فبعد فتحه وتركه في الخزانة لأكثر من 6 أشهر، قد يبدأ البيكنج باودر بفقدان فعاليته.","انتظر حتى تبرد الدونات قبل تغطيتها بالسكر والقرفة. فإذا كانت الدونات دافئة جدًا، فسيذوب الطلاء.","لا تكدّس الدونات فوق بعضها عندما تكون مغطاة حديثًا لمنع ذوبان الطلاء. ومن الأفضل ترتيبها في طبقة واحدة.","يبقى المتبقي صالحًا في درجة حرارة الغرفة أو في الثلاجة لمدة 2-3 أيام. (احفظه في الثلاجة إذا كنت في مناخ أكثر دفئًا.) أو جمّد دفعة (يُفضَّل بدون الطلاء) لمدة تصل إلى 3 أشهر وغطِّها قبل التقديم."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة","For the Cinnamon Sugar Glaze":"لطبقة السكر والقرفة","For the glaze":"للطبقة"})
R(9344030,"آيس كريم نباتي بدون خفق - ثلاث نكهات!",
"ثلاث نكهات رائعة من الآيس كريم النباتي بدون خفق! حلوى صيفية خالية من الألبان ومفيدة ولذيذة!",
"3 حصص","حصة واحدة",
["3 حبات موز مجمدة","4-6* ملاعق كبيرة حليب الصويا أو حليب نباتي من اختيارك","1 كوب فراولة مجمدة","½ ملعقة صغيرة مستخلص الفانيليا الطبيعي","1 ملعقة كبيرة شراب القيقب، اختياري","3 حبات موز مجمدة","2-3* ملاعق كبيرة حليب الصويا أو حليب نباتي من اختيارك","1½ ملعقة صغيرة قهوة سريعة التحضير، منزوعة الكافيين إن أردت","رشة ملح البحر، اختيارية","3 حبات موز مجمدة","2-3* ملاعق كبيرة حليب الصويا أو حليب نباتي من اختيارك","¼ ملعقة صغيرة مستخلص النعناع الفلفلي الطبيعي، زِدها إلى نصف ملعقة صغيرة للحصول على نكهة نعناع أقوى","¼ كوب سبانخ صغيرة (بيبي)، اختيارية","3 ملاعق كبيرة رقائق شوكولاتة نباتية، شوكولاتة داكنة أو شبه محلاة"],
["ضع جميع المكونات في محضّر الطعام أو خلاط عالي السرعة واخلطها حتى تصبح ناعمة وكريمية، مع التوقف لكشط الجوانب عند الحاجة. استمتع به فورًا للحصول على قوام الآيس كريم الطري. أو جمّده لمدة 30-60 دقيقة للحصول على قوام أكثر تماسكًا يمكن اغترافه.","ضع جميع المكونات في محضّر الطعام أو خلاط عالي السرعة واخلطها حتى تصبح ناعمة وكريمية، مع التوقف لكشط الجوانب عند الحاجة. استمتع به فورًا للحصول على قوام الآيس كريم الطري. أو جمّده لمدة 30-60 دقيقة للحصول على قوام أكثر تماسكًا يمكن اغترافه.","ضع الموز المجمد والحليب ومستخلص النعناع الفلفلي في محضّر الطعام أو خلاط عالي السرعة واخلطها حتى تصبح ناعمة وكريمية، مع التوقف لكشط الجوانب عند الحاجة. ثم أضف السبانخ (إن استخدمتها) واخلط لتمتزج.","أضف رقائق الشوكولاتة وقلّب بالنبض مرة أو مرتين لتمتزج. استمتع به فورًا للحصول على قوام الآيس كريم الطري. أو جمّده لمدة 30-60 دقيقة للحصول على قوام أكثر تماسكًا يمكن اغترافه."],
["استخدم موزًا مجمدًا ناضجًا جدًا لتحصل على أقصى حلاوة طبيعية في الآيس كريم النباتي. إذا لم يكن لديك موز في الفريزر، فتأكد من أن الموز عليه بقع كثيرة وطري. ثم قشّره وقطّعه إلى قطع وجمّده حتى يتصلب. كسّر الموز المجمد إلى قطع (إن لم يكن مقطعًا) لمساعدة المحضّر وتسهيل الخلط. * ابدأ بالكمية الأقل من الحليب النباتي ولا تزد إلا عند الحاجة. فحجم الموز هو الذي يحدد كمية الحليب اللازمة للخلط. استخدم أقل كمية ممكنة من الحليب لخلطه إلى قوام سميك وكريمي. فالإفراط في الحليب يجعل الآيس كريم رقيقًا جدًا وأقرب إلى العصير المخفوق (السموذي). السبانخ الاختيارية في آيس كريم النعناع ورقائق الشوكولاتة هي للون الأخضر وليست للنكهة. فلن تتذوق السبانخ، ولكن يمكنك الاستغناء عنها إن أردت. سيكون الآيس كريم أبيض اللون بدونها. وإذا كنت تستخدم محضّر الطعام، فستبقى قطع صغيرة من السبانخ لا تُهرس تمامًا، لكن مرة أخرى لن تتذوقها. استخدم الخلاط للحصول على قوام أنعم إذا كنت بحاجة إلى إخفاء السبانخ عن الأطفال الصعبي الإرضاء. 🙂 المعلومات الغذائية في الجدول أدناه تخص الوصفة الأساسية التي تتضمن الموز والحليب النباتي فقط. ولا تشمل النكهات الإضافية والمكونات الاختيارية. السعرات الحرارية مع المكونات الاختيارية لكل نكهة من النكهات الثلاث كما يلي: آيس كريم الفراولة والموز: 149 سعرة حرارية لثلث الوصفة. آيس كريم القهوة النباتي: 111 سعرة حرارية لثلث الوصفة. آيس كريم النعناع ورقائق الشوكولاتة: 166 سعرة حرارية لثلث الوصفة."],
{"Strawberry Banana Nice Cream":"آيس كريم الفراولة والموز","Vegan Coffee Ice Cream":"آيس كريم القهوة النباتي","Mint Chocolate Chip Nice Cream":"آيس كريم النعناع ورقائق الشوكولاتة","Strawberry Banana Nice Cream Directions":"طريقة تحضير آيس كريم الفراولة والموز","Vegan Coffee Ice Cream Directions":"طريقة تحضير آيس كريم القهوة النباتي","Mint Chocolate Chip Nice Cream Directions":"طريقة تحضير آيس كريم النعناع ورقائق الشوكولاتة"})
R(9344136,"طريقة تحضير جبن الموزاريلا النباتي",
"جبن موزاريلا نباتي يتمدد ويذوب!! بدون ألبان، فقط مرونة لذيذة مثالية للغمس أو لتغطية كل شيء!",
"6 حصص","حصة واحدة",
["½ كوب كاجو نيء أو لوز مقشّر*","¼ كوب نشا التابيوكا","2 ملعقة كبيرة خميرة غذائية","¾ ملعقة صغيرة ملح البحر","1 ملعقة كبيرة خل أبيض","1 كوب ماء"],
["ضع كل شيء في الخلاط واخلط، مبتدئًا بسرعة منخفضة ثم زِد إلى سرعة عالية حتى يصبح الخليط ناعمًا.","اسكب السائل في قدر صغير أو مقلاة واطهِه على نار متوسطة مع التحريك المستمر. سترى الخليط يتحول من سائل إلى متكتل ثم إلى كتلة كبيرة من الجبن. ستستغرق هذه العملية حوالي 3-4 دقائق. احرص على مواصلة التحريك حتى لا يحترق.","قدّمه ساخنًا مع البسكويت المالح أو الرقائق أو الخضار للغمس. أو ضعه بالملعقة على البيتزا أو في ساندويتش الجبن المشوي."],
["إذا لم يكن لديك خلاط قوي، فانقع الكاجو مسبقًا. انقعه إما طوال الليل في ماء بارد أو لمدة 30 دقيقة على الأقل في ماء شديد السخونة. سيساعد النقع على ليونته وانتفاخه مما يسهّل خلطه. إذا كان لديك خلاط فيتامكس، فلا حاجة إلى النقع أولًا. لا تستبدل نشا التابيوكا (أو دقيق التابيوكا) بمكون آخر. فالتابيوكا ضرورية للحصول على موزاريلا مطاطية. استخدم خلاطًا أصغر إن أمكن للمساعدة في الحصول على قوام أنعم. فهذا يمنح قطع الكاجو مساحة أقل لتطفو فيها. أو، بعد خلط المكونات، صفِّها عبر كيس حليب المكسرات للحصول على جبن ناعم تمامًا. أحب كيس المكسرات الأكبر والأفضل الذي أستخدمه لتحضير حليب الكاجو المنزلي. نصيحة أخيرة إذا لم يكن لديك خلاط عالي السرعة: من المفيد إضافة نصف كمية الماء فقط في البداية لخلط المكونات إلى عجينة أولًا. وبعد أن تُخلط، أضف بقية الماء واخلط لتمتزج. هذا يساعد على منع وجود قطع كاجو سائبة في الجبن. احفظ المتبقي في وعاء محكم الإغلاق في الثلاجة لمدة تصل إلى 5 أيام، وأعد تسخينه ليعود إلى قوام الغمس. أو استخدم الجبن بارداً وقطّعه شرائح أو اغرفه على الأطباق التي تريدها. ويمكنك أيضًا تجميد الجبن المطبوخ بالكامل في وعاء محكم الإغلاق مناسب للتجميد. أو يمكنك تجميد السائل (قبل الطهي) في صينية مكعبات الثلج للحصول على حصص فردية تسخّنها وتستخدمها عند الحاجة. الوصفة مقتبسة من موقع It Doesn’t Taste Like Chicken"])
R(9349443,"سلطة معكرونة البيستو النباتية",
"بيستو الريحان الطازج والبازلاء يغلّف معكرونة روتيني وطماطم الإرث ويعلوه لوز محمّص لتحصل على أفضل سلطة معكرونة بيستو نباتية.",
"4 حصص","حصة واحدة",
["8 أونصات (225 جرامًا) معكرونة روتيني أو من اختيارك","1 باينت طماطم كرزية أو عنبية مقطعة إلى نصفين (حوالي 2 كوب)","1 كوب بازلاء مجمدة مذابة","¼ كوب بصل أحمر مفروم ناعمًا","½ كوب لوز مقطع شرائح رفيعة","1 كوب أوراق ريحان طازجة مكبوسة","½ كوب بازلاء مجمدة مذابة","¼ كوب جبن بارميزان نباتي، اختياري","2 فص ثوم مقشّر","2 ملعقة كبيرة عصير ليمون، أي حوالي نصف ليمونة كبيرة","1-2 ملعقة كبيرة ماء عند الحاجة للتخفيف","ملح + فلفل حسب الرغبة"],
["اختياري: سخّن فرنك أو فرن التحميص الصغير مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية) وبطّن صينية خبز صغيرة بورق الزبدة. رتّب اللوز المقطع في طبقة واحدة واخبزه لمدة 5-8 دقائق، مع تفقده كثيرًا في نهاية الخَبز لمنع أن يصبح داكنًا جدًا. أخرجه من الفرن وضعه جانبًا.","اغلِ قدرًا كبيرًا من الماء المملح بسخاء واسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها فورًا وانقلها إلى وعاء كبير. ثم أضف بقية مكونات سلطة المعكرونة إلى الوعاء نفسه وضعه جانبًا. (ملاحظة: يمكنك الاحتفاظ ببعض الطماطم والبازلاء واللوز المحمّص لتزيين الطبق لاحقًا.)","في هذه الأثناء، ضع جميع مكونات البيستو في الخلاط واخلطها حتى تصبح ناعمة. ثم اسكب البيستو فوق سلطة المعكرونة وقلّب جيدًا.","ضعها في الثلاجة لمدة ساعة أو أكثر ثم زيّنها بالطماطم والبازلاء واللوز المحمّص الذي احتفظت به وقدّمها."],
["ملّح ماء المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة. اسلق المعكرونة حتى تصل إلى درجة \"الدنتي\". لا تُفرط في سلقها! تعني \"الدنتي\" أن المعكرونة لا تزال متماسكة بعد الطهي، مما يعطي قوامًا مثاليًا في كل لقمة. لتتأكد من أن المعكرونة لا تفرط في النضج، ابدأ بتذوقها قبل بضع دقائق من الوقت المذكور على العبوة. يجب أن تكون طرية لكنها لا تزال متماسكة. طعم سلطة معكرونة البيستو هذه رائع دافئة أو باردة، لذا يمكنك تقديمها فورًا، أو وضعها في الثلاجة لمدة ساعة أو أكثر. يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق أو وعاء مغطى بإحكام."],
{"For the Pasta Salad":"لسلطة المعكرونة","For the Pesto":"للبيستو"})
